-- Catalogo dimostrativo. Gli EAN sono fittizi (prefisso 8000000000) e servono all'Ingestion per l'abbinamento.



-- Annuncia i prodotti agli altri servizi (Analytics ne usa nome e categoria).
SELECT gen_random_uuid(), 'ProductCreated',
       json_build_object('productId', p.id, 'name', p.name, 'unit', p.unit,
                         'categoryId', c.id, 'categoryName', c.name)
FROM products p JOIN categories c ON c.id = p.category_id;
